float ndot(vec2 a, vec2 b) { 
    return a.x * b.x - a.y * b.y; 
}

float sdRhombus(vec2 uv, vec2 offset, vec2 b) {
    vec2 p = abs(uv - offset);
    float h = clamp(ndot(b - 2.0 * p, b) / dot(b, b), -1.0, 1.0);
    float d = length(p - 0.5 * b * vec2(1.0 - h, 1.0 + h));
    return d * sign(p.x * b.y + p.y * b.x - b.x * b.y);
}

float dot2(vec2 v) {
    return dot(v, v);
}

float sdTrapezoid(vec2 p, float r1, float r2, float he, vec2 uv, vec2 offset) {
    vec2 k1 = vec2(r2, he);
    vec2 k2 = vec2(r2 - r1, 2.0 * he);
    //vec2 p = abs(uv - offset);

    p.x = abs(p.x);
    vec2 ca = vec2(p.x - min(p.x, (p.y < 0.0) ? r1 : r2), abs(p.y) - he);
    vec2 cb = p - k1 + k2 * clamp(dot(k1 - p, k2) / dot2(k2), 0.0, 1.0);
    float s = (cb.x < 0.0 && ca.y < 0.0) ? -1.0 : 1.0;
    return s * sqrt(min(dot2(ca), dot2(cb)));
}

// Moon shape
float sdMoon(vec2 uv, vec2 offset, float r) {
    vec2 p = uv - offset;
    float d1 = length(p) - r;
    float d2 = length(p - vec2(r * 0.5, 0)) - r * 0.5;
    return max(d1, -d2);
}

// Circle shape
float sdCircle(vec2 uv, float r, vec2 offset) {
    return length(uv - offset) - r;
}

// Equilateral triangle shape
float sdEquilateralTriangle(vec2 uv, vec2 offset, float r) {
    const float k = sqrt(3.0);
    uv -= offset;
    uv.x = abs(uv.x) - r;
    uv.y = uv.y + r / k;
    if (uv.x + k * uv.y > 0.0) uv = vec2(uv.x - k * uv.y, -k * uv.x - uv.y) / 2.0;
    uv.x -= clamp(uv.x, -2.0 * r, 0.0);
    return -length(uv) * sign(uv.y);
}

// Pentagon shape
float sdPentagon(vec2 uv, vec2 offset, float r) {
    const vec3 k = vec3(0.809016994, 0.587785252, 0.726542528);
    vec2 p = uv - offset;
    p.x = abs(p.x);
    p -= 2.0 * min(dot(vec2(-k.x, k.y), p), 0.0) * vec2(-k.x, k.y);
    p -= 2.0 * min(dot(vec2(k.x, k.y), p), 0.0) * vec2(k.x, k.y);
    p -= vec2(clamp(p.x, -r * k.z, r * k.z), r);
    return length(p) * sign(p.y);
}

// Hexagon shape
float sdHexagon(vec2 uv, vec2 offset, float r) {
    const vec3 k = vec3(-0.866025404, 0.5, 0.577350269);
    vec2 p = uv - offset;
    p = abs(p);
    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
    p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);
    return length(p) * sign(p.y);
}

// Octagon shape
float sdOctogon(vec2 uv, vec2 offset, float r) {
    const vec3 k = vec3(-0.9238795325, 0.3826834323, 0.4142135623);
    vec2 p = uv - offset;
    p = abs(p);
    p -= 2.0 * min(dot(vec2(k.x, k.y), p), 0.0) * vec2(k.x, k.y);
    p -= 2.0 * min(dot(vec2(-k.x, k.y), p), 0.0) * vec2(-k.x, k.y);
    p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);
    return length(p) * sign(p.y);
}

// Hexagram shape
float sdHexagram(vec2 uv, vec2 offset, float r) {
    const vec4 k = vec4(-0.5, 0.8660254038, 0.5773502692, 1.7320508076);
    vec2 p = uv - offset;
    p = abs(p);
    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
    p -= 2.0 * min(dot(k.yx, p), 0.0) * k.yx;
    p -= vec2(clamp(p.x, r * k.z, r * k.w), r);
    return length(p) * sign(p.y);
}

// Pie shape
float sdPie(vec2 uv, vec2 offset, vec2 c, float r) {
    vec2 p = uv - offset;
    p.x = abs(p.x);
    float l = length(p) - r;
    float m = length(p - c * clamp(dot(p, c), 0.0, r)); // c=sin/cos of aperture
    return max(l, m * sign(c.y * p.x - c.x * p.y));
}

// Canvas color
vec3 CanvasColour(vec2 uv) {
    uv = uv * 0.5 + 0.5;
    vec3 gradientStartColor = vec3(1.0, 1.0, 1.0);
    vec3 gradientEndColor = vec3(1.0, 1.0, 1.0);
    return mix(gradientStartColor, gradientEndColor, uv.y);
}

// Main image function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;
    vec3 blendShape = CanvasColour(uv);

    float circle = sdCircle(uv, 0.1, vec2(-0.7, 0.3));
    float equilateralTriangle = sdEquilateralTriangle(uv, vec2(-0.4, 0.28), 0.1);
    float pentagon = sdPentagon(uv, vec2(-0.1, 0.28), 0.1);
    float hexagon = sdHexagon(uv, vec2(-0.71, 0.01), 0.1);
    float octogon = sdOctogon(uv, vec2(-0.41, 0.01), 0.1);
    float hexagram = sdHexagram(uv, vec2(-0.21, 0.04), 0.06);
    float pie = sdPie(uv, vec2(-0.74, -0.29), vec2(0.5, 0.5), 0.06);
    float rhombus = sdRhombus(uv, vec2(-0.17, -0.29), vec2(0.1, 0.1));
    float moon = sdMoon(uv, vec2(-0.4, -0.29), 0.06);
    float trapezoid = sdTrapezoid(uv, 0.1, 0.2, 0.2, uv, vec2(-1.1, -0.2));
    blendShape = mix(vec3(1, 0, 1), blendShape, step(0.0, circle));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, equilateralTriangle));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, pentagon));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, hexagon));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, octogon));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, hexagram));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, pie));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, rhombus));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, moon));
    blendShape = mix(vec3(0, 1, 1), blendShape, step(0.0, trapezoid));

    fragColor = vec4(blendShape, 1.0);
}
